// spec: specs/search-filters.md (1.2, 1.3) · кейсы: .qa/tests/search-filters/FILTER-PRICE-02.md, FILTER-PRICE-03.md
// seed: tests/seed.spec.ts (гость) · мобайл (Pixel 7, сценарий клиента) · прод, только чтение.
import { test, expect } from '@playwright/test';
import {
  prepareReadOnly, captureCatalog, openPage, openFilter, fields, thumbs, rangeLabel, enter, applyFilter, idsInRange,
  expectResults, thumbValue, dragThumb, thumbCenters, fmt, EnterMode, LOAD, PRICE_EDGE,
} from './search-filters.helpers';

test.use({ serviceWorkers: 'block' });

const MIN = 1_000_000;
const MAX = 3_000_000;
const VARIANTS: { mode: EnterMode; order: 'мин→макс' | 'макс→мин' }[] = [
  { mode: 'type', order: 'мин→макс' },
  { mode: 'type', order: 'макс→мин' },
  { mode: 'fill', order: 'мин→макс' },
];

test.describe('Фильтры поиска — попап «חיפוש וסינון», мобайл', () => {
  for (const v of VARIANTS) {
    test(`Попап: поля (${v.mode === 'type' ? 'по цифре' : 'вставкой'}, ${v.order}) — значения сохраняются, выдача по диапазону, при повторном открытии те же #b4b8c9 @android @prod-safe`, async ({ page, context }) => {
      await prepareReadOnly(context);
      const catalog = captureCatalog(page);
      await openPage(page, '/search');
      const expected = idsInRange(await catalog(), MIN, MAX);
      expect(expected.length, `в каталоге есть объявления ${MIN}–${MAX} — иначе данные сайта, не баг`).toBeGreaterThan(0);

      const dialog = await openFilter(page, true);
      const f = fields(dialog);
      const seq = v.order === 'мин→макс' ? [[f.min, MIN], [f.max, MAX]] as const : [[f.max, MAX], [f.min, MIN]] as const;
      await enter(seq[0][0], seq[0][1], v.mode);
      await enter(seq[1][0], seq[1][1], v.mode);
      await dialog.getByText('טווח מחירים', { exact: true }).click(); // выход из поля
      await expect(f.min, 'после ввода и выхода из поля мин на месте').toHaveValue(String(MIN));
      await expect(f.max, 'после ввода и выхода из поля макс на месте').toHaveValue(String(MAX));
      await expect(rangeLabel(dialog)).toHaveText(`${fmt(MIN)} - ${fmt(MAX)}`);

      await applyFilter(page);
      await expect(dialog, 'попап закрылся').toBeHidden(LOAD);
      await page.waitForURL(
        (u) => u.searchParams.get('minPrice') === String(MIN) && u.searchParams.get('maxPrice') === String(MAX),
        LOAD,
      );
      await expectResults(page, expected, `попап ${MIN}–${MAX}`);

      const again = await openFilter(page, true);
      const f2 = fields(again);
      const t2 = thumbs(again);
      await expect(f2.min, 'повторное открытие: мин сохранён').toHaveValue(String(MIN));
      await expect(f2.max, 'повторное открытие: макс сохранён').toHaveValue(String(MAX));
      await expect(rangeLabel(again)).toHaveText(`${fmt(MIN)} - ${fmt(MAX)}`);
      await expect(t2.min).toHaveAttribute('aria-valuenow', String(MIN));
      await expect(t2.max).toHaveAttribute('aria-valuenow', String(MAX));
    });
  }

  test('Попап: «טווח מחירים» с ₪0, две ручки двигаются независимо; выдача и повторное открытие по выбранному диапазону #b4b8c9 @android @prod-safe', async ({ page, context }) => {
    await prepareReadOnly(context);
    const catalog = captureCatalog(page);
    await openPage(page, '/search');
    const all = await catalog();

    const dialog = await openFilter(page, true);
    const t = thumbs(dialog);
    const f = fields(dialog);
    await expect(rangeLabel(dialog), 'старт диапазона — с 0').toHaveText(`₪0 - ${fmt(PRICE_EDGE)}`);
    await expect(dialog.getByRole('slider'), 'у ползунка две ручки').toHaveCount(2);
    await expect(t.min).toHaveAttribute('aria-valuemin', '0');
    await expect(t.min).toHaveAttribute('aria-valuenow', '0');
    await expect(t.max).toHaveAttribute('aria-valuenow', String(PRICE_EDGE));

    // RTL: мин справа, макс слева. Мин — на 10% ширины влево, макс — к 30% от правого края.
    const { minX, maxX } = await thumbCenters(dialog);
    const W = minX - maxX;
    await dragThumb(page, t.min, minX - W * 0.1);
    const minAfter = await thumbValue(t.min);
    expect(minAfter, 'ручка мин сдвинулась').toBeGreaterThan(0);
    await expect(t.max, 'ручка макс при этом не сдвинулась').toHaveAttribute('aria-valuenow', String(PRICE_EDGE));

    await dragThumb(page, t.max, minX - W * 0.3);
    const lo = await thumbValue(t.min);
    const hi = await thumbValue(t.max);
    expect(lo, 'ручка мин не сдвинулась вместе с макс').toBe(minAfter);
    expect(hi, 'ручка макс сдвинулась и осталась правее мин по значению').toBeLessThan(PRICE_EDGE);
    expect(hi).toBeGreaterThan(lo);
    await expect(f.min, 'поле мин = ручка мин').toHaveValue(String(lo));
    await expect(f.max, 'поле макс = ручка макс').toHaveValue(String(hi));
    await expect(rangeLabel(dialog)).toHaveText(`${fmt(lo)} - ${fmt(hi)}`);

    await applyFilter(page);
    await expect(dialog).toBeHidden(LOAD);
    await page.waitForURL(
      (u) => u.searchParams.get('minPrice') === String(lo) && u.searchParams.get('maxPrice') === String(hi),
      LOAD,
    );
    await expectResults(page, idsInRange(all, lo, hi), `ползунок ${lo}–${hi}`);

    const again = await openFilter(page, true);
    await expect(thumbs(again).min).toHaveAttribute('aria-valuenow', String(lo));
    await expect(thumbs(again).max).toHaveAttribute('aria-valuenow', String(hi));
    await expect(fields(again).min).toHaveValue(String(lo));
    await expect(fields(again).max).toHaveValue(String(hi));
  });
});
